Lemma fsobj_cons : forall LF f O n, fsobj H LF O n -> fsobj H (f :: LF) O n.
Proof. intros LF f O n [K|(g & IN & K1 & K2)]; [left; exact K| right; exists g; split; [right; exact IN| split; assumption]]. Qed.

(* [comment removed for export] *)
Definition sc_invt (s : as_St H) (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi spa ff fp : Z) (sp : word)
    (saved gap : list cell) (h32 j472 shb : list byte) (errv : word) (cs lc : list cell) (m : mem) : Prop :=
     rw_cells asegs m spa lc /\ Z.of_nat (cells_size lc) = 80
  /\ rw_cells asegs m (spa + 80) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 80)
  /\ rw_cells asegs m (bv_unsigned sp + -104) saved /\ Z.of_nat (cells_size saved) = 104
  /\ rw_cells asegs m ff [CB 32 h32; CB 472 j472; C8 (Z_to_bv 64 fp)]
  /\ rw_cells asegs m (Z.shiftr ff 3 + 2147450880) [CB 64 shb]
  /\ rw_cells asegs m fp [C1 (b8 1)]
  /\ rw_cells asegs m S cs /\ Z.of_nat (cells_size cs) = 272 /\ addressable m S NEWSZ_SCH
  /\ stk asegs m lo spa /\ mem_inv asegs m
  /\ asc_inv LB m ioc regb cfgb errv
  /\ as_RHEAP H s LB m /\ as_RFS H ((3, ff, fp) :: LF) m /\ ACONST m /\ stack0 m lo shi.

(* [comment removed for export] *)
Definition sc_side (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi spa ff fp : Z) (sp tp : word) : Prop :=
     asc_pure H S ioc regb cfgb lo shi sp tp (Z_to_bv 64 0) /\ asc_fs H LF S ioc regb cfgb /\ fresh_frame H LF 3 ff fp
  /\ (exists p, In (p, S, NEWSZ_SCH) LB) /\ (spa = bv_unsigned sp + -192 \/ spa = bv_unsigned sp + -208) /\ (length LF + 1 < AFS_MAXLIVE)%nat
  /\ (S + NEWSZ_SCH <= ff \/ ff + 512 <= S) /\ (S + NEWSZ_SCH <= fp \/ fp + 1 <= S).
